import { CardData } from '../../paymentTypes';

// Generate a UUID v4
function generateUUID(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  }).toUpperCase();
}

// Format date to MM/DD/YYYY HH:MM:SS AM/PM TZ
function formatTimestamp(date: Date): string {
  const options: Intl.DateTimeFormatOptions = {
    month: '2-digit',
    day: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: true,
    timeZoneName: 'short',
  };
  return date.toLocaleString('en-US', options).replace(',', '');
}

// Simple hash for checksum display
async function generateChecksum(data: string): Promise<string> {
  const encoder = new TextEncoder();
  const dataBuffer = encoder.encode(data);
  const hashBuffer = await crypto.subtle.digest('SHA-256', dataBuffer);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// Get user's IP address (best effort)
async function getUserIP(): Promise<string> {
  try {
    const res = await fetch('https://api.ipify.org?format=json');
    const data = await res.json();
    return data.ip || 'Unknown';
  } catch {
    return 'Unknown';
  }
}

// Detect browser/OS
function getBrowserInfo(): string {
  const ua = navigator.userAgent;
  let browser = 'Unknown Browser';
  let os = 'Unknown OS';

  if (ua.includes('Chrome') && !ua.includes('Edg')) browser = 'Chrome';
  else if (ua.includes('Safari') && !ua.includes('Chrome')) browser = 'Safari';
  else if (ua.includes('Firefox')) browser = 'Firefox';
  else if (ua.includes('Edg')) browser = 'Edge';

  if (ua.includes('Windows')) os = 'Windows';
  else if (ua.includes('Mac')) os = 'macOS';
  else if (ua.includes('iPhone') || ua.includes('iPad')) { os = 'iOS'; if (ua.includes('CriOS')) browser = 'Chrome Mobile iOS'; else browser = 'Mobile Safari'; }
  else if (ua.includes('Android')) { os = 'Android'; browser = 'Chrome Mobile'; }
  else if (ua.includes('Linux')) os = 'Linux';

  return `${browser} via ${os}`;
}

export interface CertificateData {
  referenceNumber: string;
  sentAt: string;
  executedAt: string;
  signerName: string;
  lastName: string;
  reservationNumber: string;
  cardBrand: string;
  signerEmail: string;
  signatureDataUrl: string;
  ipAddress: string;
  browserInfo: string;
  checksum: string;
  amount: string;
  cardType: string;
  maskedCardNumber: string;
  phoneNumber: string;
  billingAddress: string;
  currency: string;
  date: string;
}

export async function buildCertificateData(formData: CardData): Promise<CertificateData> {
  const referenceNumber = generateUUID();
  const now = new Date();
  const sentAt = formatTimestamp(new Date(now.getTime() - 5 * 60 * 1000)); // 5 min before
  const executedAt = formatTimestamp(now);
  const ipAddress = await getUserIP();
  const browserInfo = getBrowserInfo();

  const fullName = formData.name || formData.firstName;
  const reservationNumber = formData.lastName || '';

  const checksumSource = `${referenceNumber}|${fullName}|${formData.email}|${formData.number}|${executedAt}`;
  const checksum = await generateChecksum(checksumSource);

  // Mask card number for certificate: only show last 4 digits
  const cleanNum = (formData.number || '').replace(/\D/g, '');
  const last4 = cleanNum.slice(-4) || '••••';
  const maskedCardNumber = `•••• •••• •••• ${last4}`;

  const billingAddress = `${formData.address}${formData.addressLine2 ? ', ' + formData.addressLine2 : ''}, ${formData.city}, ${formData.state} ${formData.postalCode}, ${formData.country}`;
  const phoneNumber = `${formData.phoneCode} ${formData.phoneNumber}`;

  return {
    referenceNumber,
    sentAt,
    executedAt,
    signerName: fullName,
    lastName: reservationNumber,
    reservationNumber,
    cardBrand: formData.cardBrand || 'Visa',
    signerEmail: formData.email,
    signatureDataUrl: formData.cardholderSignature,
    ipAddress,
    browserInfo,
    checksum,
    amount: formData.amount,
    cardType: formData.paymentType || 'Credit Card',
    maskedCardNumber,
    phoneNumber,
    billingAddress,
    currency: formData.currency || 'CAD',
    date: formData.date || new Date().toISOString().split('T')[0],
  };
}

